  # Enforce enterprise Amazon EKS architectural baseline (Tier-1)
  tags = {
    Environment      = var.environment
    Compliance       = "CIS AWS 2.1.1"
    SecurityPillar   = "Reliability"
    ManagedBy        = "Terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

mermaid:
flowchart TB
  client["Application client"]
  service@{ icon: "logos:k8s-service", label: "Service: selector and targetPort", h: 64, pos: "b" }
  pods@{ icon: "logos:k8s-pod", label: "Ready application Pods", h: 64, pos: "b" }
  resource@{ icon: "logos:container-eks", label: "Amazon EKS", h: 64, pos: "b" }
  registry@{ icon: "logos:container-registry", label: "Image registry: immutable digest", h: 64, pos: "b" }
  control["Enforce IAM Roles for Service Accounts (IRSA) via OIDC Federation"]
  client -->|Configured ingress or cluster-local request| service
  service -->|targetPort to ready endpoints| pods
  resource -.->|Workload or routing configuration| pods
  registry -.->|Image pull by node or runtime identity| pods
  control -.->|Implementation requirement| resource

